decompress_inputs.run:
try:
    shell("""
        echo "🗜️ Decompressing FASTA and GTF next to originals"
        gunzip -c {input.fasta_gz} > {output.fasta}
        gunzip -c {input.gtf_gz}   > {output.gtf}
    """)
except Exception as e:
    update_step_status(EXP_ID, "processing", "failed")
    raise e

prep_circtools_sample.run:
shell("""
set -euo pipefail

# fail fast if STAR outputs are empty
for f in {input.sam} {input.junction} {input.mate1_junc} {input.mate2_junc}; do
    if [ ! -s "$f" ]; then
        echo "ERROR: Missing or empty STAR output: $f"
        exit 1
    fi
done

# create expected SJ filename for circtools
ln -sf {wildcards.sample}_SJ.out.tab run_output/alignment/{wildcards.sample}/SJ.out.tab

mkdir -p run_output/alignment/{wildcards.sample}/tmp_sort

samtools view -h {input.sam} \
| awk 'BEGIN {OFS="\t"}
  /^@/ {print; next}
  {
    split($6,C,/[0-9]*/);
    split($6,L,/[SMDIN]/);

    if (C[2]=="S") {
      $10=substr($10,L[1]+1);
      $11=substr($11,L[1]+1)
    }

    if (C[length(C)]=="S") {
      L1=length($10)-L[length(L)-1];
      $10=substr($10,1,L1);
      $11=substr($11,1,L1)
    }

    gsub(/[0-9]*S/,"",$6);
    print
  }' \
| samtools view -bS - \
| samtools sort -@ {threads} \
    -T run_output/alignment/{wildcards.sample}/tmp_sort \
    -o {output.bam}

samtools index {output.bam}

# meta detection
if [[ -s {input.mate1_junc} && -s {input.mate2_junc} ]]; then
    echo "OLD" > {output.meta}
else
    echo "NEW" > {output.meta}
fi
""")

prep_circtools_finalize.run:
shell("""
set -euo pipefail

: > {output.bamlist}
: > {output.mate1}
: > {output.mate2}
: > {output.sheet}

for sample in {SAMPLES}; do

    echo "run_output/alignment/${{sample}}/${{sample}}_Aligned.noS.bam" >> {output.bamlist}

    echo "run_output/alignment/${{sample}}/${{sample}}_Chimeric.out.junction" >> {output.sheet}

    style=$(cat run_output/circtools_ci/${{sample}}.meta)

    if [[ "$style" == "OLD" ]]; then
        echo "run_output/alignment/${{sample}}/${{sample}}.mate1_Chimeric.out.junction" >> {output.mate1}
        echo "run_output/alignment/${{sample}}/${{sample}}.mate2_Chimeric.out.junction" >> {output.mate2}
    else
        echo "run_output/alignment/${{sample}}/${{sample}}_Chimeric.out.junction" >> {output.mate1}
    fi

done

touch {output.done}
""")

build_bwa_index.run:
try:
    update_step_status(EXP_ID, "ciriquant", "running")

    shell("""
        mkdir -p {params.index_dir}
        bwa index -a bwtsw \\
                   -p {params.index_prefix} \\
                   {input.fasta}
    """)

except Exception as e:
    update_step_status(EXP_ID, "ciriquant", "failed")
    raise e

build_hisat2_index.run:
try:
    update_step_status(EXP_ID, "ciriquant", "running")

    shell("""
        source /etc/profile.d/modules.sh
        module load hisat2
        mkdir -p {params.index_dir}
        hisat2-build -p {threads} {input.fasta} {params.index_prefix}
    """)

except Exception as e:
    update_step_status(EXP_ID, "ciriquant", "failed")
    raise e
